package store
import("path/filepath";"testing";"time")
func TestClusterEndpointAndConnectivityHistory(t *testing.T){s,e:=Open(filepath.Join(t.TempDir(),"x.db"));if e!=nil{t.Fatal(e)};defer s.Close();if e=s.RecordClusterEndpoint(ClusterEndpointReceipt{NodeID:"ul7",Machine:"UL7",Listen:"0.0.0.0:8787",Advertise:"http://ul7:8787",Peers:"http://oda:8787"});e!=nil{t.Fatal(e)};eps,e:=s.ClusterEndpoints();if e!=nil||len(eps)!=1||eps[0].Advertise!="http://ul7:8787"{t.Fatalf("endpoints=%+v err=%v",eps,e)};if e=s.RecordClusterConnectivity(ClusterConnectivity{ObserverNodeID:"ul7",TargetEndpoint:"http://oda:8787",TargetNodeID:"oda",TargetMachine:"ODA",OK:true,LatencyMS:12,ObservedAt:time.Now().UTC()});e!=nil{t.Fatal(e)};rows,e:=s.ClusterConnectivityHistory(10);if e!=nil||len(rows)!=1||!rows[0].OK||rows[0].LatencyMS!=12{t.Fatalf("rows=%+v err=%v",rows,e)}}
